-- Transiva Auth 2.6.1. Select your application database in phpMyAdmin first.

-- MySQL 8+ or MariaDB 10.6+. For older versions use the PHP CLI migration.

-- Pause registration/profile writes during import. Backup first. No users are deleted.

-- Preflight duplicates: resolve these before continuing if any rows are returned.

SELECT LOWER(TRIM(username)) AS duplicate_username, GROUP_CONCAT(id) AS user_ids FROM users WHERE TRIM(username)<>'' GROUP BY LOWER(TRIM(username)) HAVING COUNT(*)>1;

SELECT LOWER(TRIM(email)) AS duplicate_customer_email, GROUP_CONCAT(id) AS user_ids FROM users WHERE LOWER(TRIM(role))='customer' AND TRIM(COALESCE(email,''))<>'' GROUP BY LOWER(TRIM(email)) HAVING COUNT(*)>1;

