HEN LEFT((CASE WHEN LEFT(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),4)='0062' THEN SUBSTRING(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),3) ELSE REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]','') END),1)='0' THEN SUBSTRING((CASE WHEN LEFT(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),4)='0062' THEN SUBSTRING(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),3) ELSE REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]','') END),2) ELSE (CASE WHEN LEFT(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),4)='0062' THEN SUBSTRING(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),3) ELSE REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]','') END) END)) END) WHERE LOWER(TRIM(role))='customer';

