CREATE TABLE IF NOT EXISTS customer_registration_receipts(operation_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,request_hash CHAR(64) CHARACTER SET ascii NOT NULL,password_proof VARCHAR(255) NOT NULL,response_json MEDIUMTEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS customer_email_challenges(user_id INT NOT NULL PRIMARY KEY,email VARCHAR(254) NOT NULL,otp_hash VARCHAR(255) NULL,expires_at DATETIME NULL,resend_after DATETIME NULL,attempts INT NOT NULL DEFAULT 0,proof_hash CHAR(64) NULL,proof_expires_at DATETIME NULL,consumed_at DATETIME NULL) ENGINE=InnoDB;

SET @transiva_auth_sql=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='customer_registration_receipts' AND COLUMN_NAME='password_proof'), 'SELECT 1', 'ALTER TABLE customer_registration_receipts ADD COLUMN password_proof VARCHAR(255) NULL');

PREPARE transiva_auth_stmt FROM @transiva_auth_sql; EXECUTE transiva_auth_stmt; DEALLOCATE PREPARE transiva_auth_stmt;

-- Verify all three tables are InnoDB. This script does not convert the live users table automatically.

SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('users','customer_registration_receipts','customer_email_challenges');

